def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---------------- 127.95 Construction Technology / Core (safety, math, tools, drawings) ----------------
H('95.d.1.A',2,"In a safety culture, who is responsible for jobsite safety?","Everyone on the site",["Only the owner","Only the inspector","Only the newest worker"],"A safety culture means all workers share responsibility.")
H('95.d.1.A',3,"A crew where workers stop unsafe tasks and look out for each other is showing a:","Strong safety culture",["Weak reputation","Slow schedule","Loose budget"],"Shared values and habits make a safety culture.")
H('95.d.1.B',3,"Why is a safety culture especially important in the construction crafts?","Work involves heights, heavy loads, and powered tools",["Tools are always lightweight","Sites are always indoors","Hazards never change"],"Construction hazards are many and serious.")
H('95.d.1.B',4,"A contractor with a strong safety culture will usually see fewer:","Injuries and lost workdays",["Customers","Blueprints","Deliveries"],"Safety reduces injuries and downtime.")
H('95.d.1.C',3,"OSHA stands for:","Occupational Safety and Health Administration",["Organized Site Housing Agency","Official Safety and Hazard Association","Office of Skilled Home Architecture"],"OSHA is the federal workplace safety agency.")
H('95.d.1.C',4,"One thing OSHA does on construction sites is:","Set and enforce safety standards through inspections",["Hire the crew","Supply the lumber","Draw the blueprints"],"OSHA inspects and issues citations.")
H('95.d.1.D',3,"OSHA generally requires fall protection for construction work at or above:","6 feet",["1 foot","2 feet","20 feet"],"Six feet is the construction trigger height.")
H('95.d.1.D',4,"A safe way to use an extension ladder is to set it so the base is one foot out for every:","4 feet of height",["10 feet of height","1 foot of height","20 feet of height"],"The 4-to-1 rule gives a safe angle.")
H('95.d.1.E',3,"Safety glasses are worn on a jobsite to protect the:","Eyes",["Ears","Knees","Elbows"],"Eye protection stops flying debris.")
H('95.d.1.E',4,"Before each use, a worker should inspect PPE such as a harness for:","Cuts, fraying, or damage",["Color choice","Brand name","Logo size"],"Damaged PPE may fail.")
H('95.d.1.F',3,"Before drilling into a wall, a worker should consider that the wall may contain:","Live electrical wiring",["Only air","Only paint","Only sunlight"],"Hidden wiring is a shock hazard.")
H('95.d.1.F',4,"Lockout/tagout is used to make sure equipment cannot be:","Energized while someone is working on it",["Painted","Moved by hand","Delivered"],"It protects workers from unexpected startup.")
H('95.d.1.G',3,"A Safety Data Sheet (SDS) is used to learn about:","The hazards and safe use of a product",["The price of a product","The paint color","The supplier's holidays"],"SDS lists hazards, first aid, and handling.")
H('95.d.1.G',4,"Where must SDS binders be kept on a jobsite?","Where workers can get to them during their shifts",["Locked in an office off site","In the owner's home","In a truck far away"],"Access must be quick, especially in emergencies.")
H('95.d.2.A',3,"Most jobsite accidents are caused by:","Unsafe acts and unsafe conditions",["Good planning","Clear walkways","Proper training"],"Both behaviors and conditions cause accidents.")
H('95.d.2.A',4,"Rushing a job and skipping steps is an example of an:","Unsafe act",["Safe condition","Engineering control","Code requirement"],"Unsafe acts come from human choices.")
H('95.d.2.B',3,"Besides medical bills, an accident can also cost a company:","Lost time, higher insurance, and delays",["Free advertising","Lower taxes","Faster schedules"],"Indirect costs add up.")
H('95.d.2.B',4,"Indirect costs of accidents are costs that:","Are not billed directly but still hurt the business",["Are always covered by insurance","Never occur","Are paid by the customer"],"Hidden costs include lost productivity.")
H('95.d.2.C',3,"Hazard recognition means being able to:","Spot dangerous conditions before someone is hurt",["Ignore warnings","Fix injuries","Order materials"],"Recognizing hazards allows prevention.")
H('95.d.2.C',4,"A worker walking a site at the start of a shift and noting hazards is practicing:","Hazard recognition",["Estimating","Scheduling","Layout"],"Walk-throughs help find hazards early.")
H('95.d.2.D',3,"A struck-by hazard occurs when a worker is hit by:","A moving or falling object",["A cold breeze","A phone call","A memo"],"Falling tools and swinging loads strike workers.")
H('95.d.2.D',4,"Wearing a hard hat helps protect against which hazard?","Struck-by",["Chemical splash only","Noise only","Heat only"],"Hard hats absorb impacts from above.")
H('95.d.2.E',3,"A caught-in-between hazard exists when a worker can be:","Squeezed or crushed between objects",["Left waiting","Given extra pay","Sent home early"],"Examples include trench cave-ins and machinery pinch points.")
H('95.d.2.E',4,"Which situation is a caught-in-between hazard?","Working in an unprotected deep trench",["Carrying a tape measure","Sweeping a floor","Reading a plan"],"Trench walls can collapse and bury workers.")
H('95.d.2.F',3,"An example of a hazardous material on a jobsite is:","Asbestos-containing insulation",["A paper cup","A clean towel","A plastic ruler"],"Asbestos fibers harm the lungs.")
H('95.d.2.F',4,"Besides falls and struck-by hazards, workers face electrocution hazards such as:","Contact with overhead power lines",["Warm weather","Quiet rooms","Soft flooring"],"Power lines can carry deadly voltage.")
H('95.d.2.G',3,"Hazard communication (HazCom) makes sure workers are told about:","The chemical hazards they may be exposed to",["Next week's lunch","The owner's vacation","The weather forecast"],"HazCom requires labels, SDS, and training.")
H('95.d.2.G',4,"A HazCom container label must identify the:","Product and its hazards",["Delivery driver","Store hours","Crew size"],"Labels warn of dangers.")
H('95.d.3.A',3,"A carpenter has 48 boards and uses 17. How many remain?","31",["65","29","41"],"48 - 17 = 31.")
H('95.d.3.A',4,"A crew installs 18 sheets of drywall per room in 7 rooms. How many sheets are installed?","126",["25","108","144"],"18 x 7 = 126.")
H('95.d.3.B',3,"What is 1/2 + 1/4 of an inch?","3/4 inch",["2/6 inch","1/8 inch","1 inch"],"1/2 = 2/4; 2/4 + 1/4 = 3/4.")
H('95.d.3.B',4,"A board 5/8 inch thick is planed down by 1/8 inch. What is the new thickness?","1/2 inch",["3/4 inch","1/4 inch","6/8 inch"],"5/8 - 1/8 = 4/8 = 1/2.")
H('95.d.3.C',3,"A pipe is 2.5 feet long. Another is 1.75 feet. What is their total length?","4.25 feet",["3.25 feet","4.75 feet","3.75 feet"],"2.5 + 1.75 = 4.25.")
H('95.d.3.C',4,"Nails cost $0.12 each. What do 25 nails cost?","$3.00",["$0.30","$2.50","$12.00"],"0.12 x 25 = 3.00.")
H('95.d.3.D',3,"The decimal 0.25 is the same as what percentage?","25 percent",["2.5 percent","0.25 percent","250 percent"],"Multiply by 100.")
H('95.d.3.D',4,"A 15 percent tax rate is written as which decimal?","0.15",["1.5","15.0","0.015"],"Divide the percent by 100.")
H('95.d.3.E',3,"The fraction 3/4 equals which decimal?","0.75",["0.34","0.43","3.4"],"3 divided by 4 = 0.75.")
H('95.d.3.E',4,"The decimal 0.125 is the same as which fraction?","1/8",["1/4","1/5","1/12"],"0.125 = 125/1000 = 1/8.")
H('95.d.4.A',3,"On a standard tape measure, the smallest tick marks usually show:","16ths of an inch",["Half inches","Feet","Yards"],"Most tapes mark sixteenths.")
H('95.d.4.A',4,"An architect's scale is used to:","Measure lines on drawings at a reduced size",["Weigh lumber","Level a wall","Cut metal"],"Scales let you read dimensions from a drawing.")
H('95.d.4.B',3,"The metric system is based on units of:","Ten",["Twelve","Sixteen","Five"],"It is a base-10 system.")
H('95.d.4.B',4,"The metric system matters in construction because many products and plans:","Are made or specified in metric units",["Never use metric","Only use feet","Are always in yards"],"Global products often use metric.")
H('95.d.4.C',3,"Which metric unit measures length?","Meter",["Liter","Gram","Celsius"],"The meter is the base unit of length.")
H('95.d.4.C',4,"Which metric unit measures volume of liquid?","Liter",["Meter","Kilogram","Newton"],"Liters measure volume.")
H('95.d.4.D',3,"A common shape used when laying out a room's floor is the:","Rectangle",["Star","Heart","Spiral"],"Most rooms are rectangular.")
H('95.d.4.D',4,"A triangle is used in roof framing because it is:","A very rigid shape",["Easy to bend","Always weak","Flexible"],"Triangles resist deformation.")
H('95.d.5.A',3,"A claw hammer is mainly used to:","Drive and pull nails",["Measure","Cut pipe","Weld steel"],"The claw pulls nails.")
H('95.d.5.A',4,"A tool used to mark a straight line over a long distance is a:","Chalk line",["Pipe wrench","Plumb bob","Wire stripper"],"Snapped chalk marks straight lines.")
H('95.d.5.B',3,"Before using a hammer, a worker should check that the:","Handle is not cracked and the head is tight",["Brand is famous","Color is bright","Price tag is attached"],"A loose head can fly off.")
H('95.d.5.B',4,"A mushroomed chisel head is unsafe because pieces can:","Chip off and strike the user",["Make it quieter","Make it lighter","Sharpen the blade"],"Damaged heads should be dressed or replaced.")
H('95.d.5.C',3,"When using a utility knife, cut:","Away from your body",["Toward your hand","Toward your legs","With the blade fully extended always"],"Cutting away avoids injury.")
H('95.d.5.C',4,"A handsaw cuts best when you:","Let the saw do the work with smooth strokes",["Force it hard","Twist it","Cut fast and loose"],"Proper technique is safer and cleaner.")
H('95.d.6.A',3,"A tool powered by electricity and used to drive screws is a:","Cordless drill/driver",["Level","Hand plane","Chalk line"],"Drill/drivers are common powered hand tools.")
H('95.d.6.A',4,"A circular saw is a powered hand tool used to:","Make straight cuts in boards and sheet goods",["Drive nails by hand","Measure angles","Mix mortar"],"It has a rotating blade.")
H('95.d.6.B',3,"Before changing a blade on a corded saw, you should:","Unplug it",["Turn it faster","Remove the guard permanently","Hold the trigger"],"Disconnect power first.")
H('95.d.6.B',4,"When using a power saw, keep the cord:","Clear of the cutting path",["Over the blade","Wrapped around your arm","Under the board"],"A cut cord is a shock hazard.")
H('95.d.6.C',3,"To maintain a power tool, you should regularly:","Clean it and check the cord and guards",["Soak it in water","Paint the motor","Remove the safety switch"],"Maintenance extends life and safety.")
H('95.d.6.C',4,"A power tool with a damaged cord should be:","Taken out of service until repaired",["Used carefully","Taped and used","Used outdoors only"],"Damaged cords are dangerous.")
H('95.d.7.A',3,"On a drawing, a dimension of 10'-6\" means:","10 feet 6 inches",["10 inches 6 feet","106 feet","10.6 feet"],"Feet and inches are separated by a dash.")
H('95.d.7.A',4,"Use dimensions on a drawing instead of measuring the drawing because:","Prints may be scaled or distorted",["Dimensions are random","Rulers are banned","Measuring is illegal"],"Written dimensions are the authority.")
H('95.d.7.B',3,"The term 'footing' in construction refers to the:","Base that supports a foundation wall",["Roof peak","Window trim","Doorknob"],"Footings spread loads into soil.")
H('95.d.7.B',4,"A 'stud' in wall framing is a:","Vertical framing member",["Door handle","Nail gun","Insulation roll"],"Studs make up the wall frame.")
H('95.d.7.C',3,"The title block on a drawing gives:","The project name, sheet number, and date",["The weather","Pay rates","The tool list"],"It identifies the sheet.")
H('95.d.7.C',4,"A north arrow on a site plan shows:","Orientation of the site",["Wind speed","The roof pitch","Soil depth"],"It helps position the building.")
H('95.d.7.D',3,"On drawings, symbols are explained in the:","Legend or symbol key",["Phone book","Weather report","Invoice"],"Always check the legend.")
H('95.d.7.D',4,"A dashed line on a plan often represents:","A hidden or future item",["The north point","A person","A dimension"],"Hidden lines show items out of view.")
H('95.d.7.E',3,"To relate a drawing to the jobsite, a builder uses:","Dimensions and reference points",["Guesswork","Colors","Rumors"],"Layout transfers plan to site.")
H('95.d.7.E',4,"A grid line labeled 'B' on the plan helps crews find:","A specific column or wall line on site",["The owner","The bank","The weather"],"Grid lines locate features.")
H('95.d.7.F',3,"A drawing showing a building from the front is a(n):","Elevation",["Plan","Section","Schedule"],"Elevations show vertical faces.")
H('95.d.7.F',4,"A drawing that shows the layout of a floor from above is a(n):","Plan",["Elevation","Detail","Section"],"Plans are overhead views.")
H('95.d.8.A',3,"When reading written instructions for installing a product, a worker should:","Follow the steps in order",["Skip to the end","Ignore warnings","Change the order"],"Order often matters.")
H('95.d.8.A',4,"A change order in writing tells the crew about:","A modification to the original work",["The weather forecast","Their breaks","Their hours only"],"Written changes must be followed.")
H('95.d.8.B',3,"After a supervisor gives verbal instructions, a worker should:","Repeat the key points to confirm them",["Walk away silently","Guess","Do something else"],"Confirming prevents errors.")
H('95.d.8.B',4,"If you don't understand a spoken instruction, the best response is to:","Ask for clarification",["Pretend you understood","Guess","Wait to be fired"],"Questions avoid mistakes.")
H('95.d.8.C',3,"Good communication on a crew is clear, polite, and:","Complete",["Rude","Vague","Hidden"],"Complete messages avoid confusion.")
H('95.d.8.C',4,"A short, accurate daily note about work completed is an example of effective:","Written communication",["Verbal gossip","Silent work","Guessing"],"Writing creates records.")
H('95.d.8.D',3,"Using a phone on a jobsite should be done:","Safely and professionally",["While operating saws","On ladders carelessly","While driving equipment"],"Distraction causes injuries.")
H('95.d.8.D',4,"A professional text to a supervisor about a delay should be:","Brief, clear, and respectful",["Full of slang","Angry","Unrelated"],"Professionalism matters in all media.")
H('95.d.9.A',3,"In material handling, a load is any:","Object being lifted, carried, or moved",["Empty room","Idea","Tape measure only"],"Loads can be heavy or awkward.")
H('95.d.9.A',4,"The weight of a load matters because it affects the:","Method and equipment needed to move it safely",["Color of paint","Temperature","Mood of the crew"],"Heavier loads need aids.")
H('95.d.9.B',3,"A pre-task plan for moving a load should identify the:","Route, hazards, and help needed",["Favorite music","Lunch menu","Brand of boots"],"Planning prevents accidents.")
H('95.d.9.B',4,"Before moving a heavy bundle of pipe, you should first:","Plan the path and clear obstacles",["Lift quickly","Lift alone","Run with it"],"Preparation is part of safe handling.")
H('95.d.9.C',3,"To lift safely, keep your back straight and lift with your:","Legs",["Back","Arms only","Neck"],"Legs are stronger than the back.")
H('95.d.9.C',4,"When two workers carry a long plank, they should:","Communicate and lift together",["Lift at different times","Drop it","Race"],"Coordination avoids injuries.")
H('95.d.9.D',3,"To move a heavy load across a flat site, a good choice is a:","Hand truck or cart",["Pencil","Clipboard","Tape measure"],"Mechanical aids reduce strain.")
H('95.d.9.D',4,"A load that is too heavy for one person should be moved with:","A team or mechanical equipment",["Brute force alone","Jerking motions","Running"],"Equipment keeps workers safe.")
H('95.d.9.E',3,"Wear gloves when handling rough lumber to prevent:","Splinters and cuts",["Sunburn","Boredom","Thirst"],"Gloves protect hands.")
H('95.d.9.E',4,"A common material-handling hazard is a:","Pinch point between a load and a wall",["Soft cushion","Clear floor","Wide aisle"],"Pinch points can crush fingers.")

# ---------------- 127.96 Building Maintenance and Finish Carpentry ----------------
H('96.d.1.A',3,"A safe procedure before starting a repair on an existing building is to:","Check for hazards like asbestos, lead paint, and live wires",["Start demolition immediately","Skip PPE","Remove warning signs"],"Older buildings may hold hidden hazards.")
H('96.d.1.A',4,"When doing building maintenance in an occupied building, workers should:","Barricade the area and warn occupants",["Leave tools in hallways","Work without warning","Block exits"],"Protecting occupants is part of safe procedure.")
H('96.d.1.B',3,"OSHA was created to:","Help ensure safe and healthful working conditions",["Pay workers","Sell tools","Draw plans"],"OSHA sets and enforces standards.")
H('96.d.1.B',4,"On a maintenance crew, promoting on-site safety includes:","Reporting hazards and following posted rules",["Hiding hazards","Ignoring rules","Skipping briefings"],"Everyone helps promote safety.")
H('96.d.1.C',3,"A worksite hazard in a maintenance shop might be:","Exposed blades on a table saw",["A clean floor","A closed cabinet","A labeled bin"],"Missing guards are a hazard.")
H('96.d.1.C',4,"To minimize a slip hazard, a maintenance worker should:","Clean spills right away and post a warning",["Ignore the spill","Walk around it","Cover it with a rag and leave"],"Controls reduce hazards.")
H('96.d.1.D',3,"Supervisors have the obligation to:","Provide training and a safe worksite",["Skip training","Avoid inspections","Hide accidents"],"Employers must provide safety.")
H('96.d.1.D',4,"A worker's safety obligation includes:","Following safe practices and using PPE",["Removing guards","Ignoring signs","Working impaired"],"Workers have duties too.")
H('96.d.1.E',3,"Accident costs include the injured worker's pain and the employer's:","Lost productivity and higher insurance",["Lower taxes","Faster work","Extra tools"],"Accidents are costly.")
H('96.d.1.E',4,"Investigating the cause of an accident helps to:","Prevent it from happening again",["Assign blame only","Delay the job","Hide records"],"Learning prevents repeats.")
H('96.d.1.F',3,"When using solvents and adhesives, ensure the area has:","Good ventilation",["No light","No exits","Closed windows only"],"Fumes can be harmful.")
H('96.d.1.F',4,"Hazardous chemicals should be kept in their:","Original labeled containers",["Unmarked jars","Food bottles","Open buckets"],"Labels carry hazard info.")
H('96.d.1.G',3,"Hearing protection is needed when working near:","Loud power equipment",["Quiet rooms","Tape measures","Books"],"Noise can damage hearing.")
H('96.d.1.G',4,"A dust mask or respirator protects the:","Lungs",["Eyes","Feet","Knees"],"Respiratory PPE filters air.")
H('96.d.1.H',3,"Lead-based paint is a particular concern in buildings built before:","1978",["2010","1995","2005"],"Lead paint was banned for homes in 1978.")
H('96.d.1.H',4,"If you suspect asbestos in old ceiling tile, you should:","Stop work and notify a supervisor",["Break it up","Sweep it dry","Burn it"],"Disturbing asbestos releases fibers.")
H('96.d.2.A',3,"A set of plans typically includes floor plans, elevations, sections, and:","Details and schedules",["Menus","Song lists","Receipts"],"These sheets show how to build.")
H('96.d.2.A',4,"The sheet that shows a building's exterior sides is the:","Elevation",["Plumbing riser","Footing detail","Door schedule"],"Elevations show faces.")
H('96.d.2.B',3,"On a blueprint, a thick solid line usually shows:","Visible object outlines",["Hidden objects","Dimensions","Center lines"],"Line weights communicate meaning.")
H('96.d.2.B',4,"A long-short-long dashed line is typically used for a:","Center line",["Property line","Wall edge","Section cut"],"Center lines show symmetry.")
H('96.d.2.C',3,"A symbol showing a duplex receptacle is part of the:","Electrical set",["Roof framing","Foundation","Site grading"],"Electrical symbols mark outlets and switches.")
H('96.d.2.C',4,"A small circle with 'S' next to a door often indicates a:","Switch",["Sink","Stairs","Slab"],"Check the legend for symbol meanings.")
H('96.d.2.D',3,"Architectural symbols may indicate:","Materials like brick, concrete, and insulation",["Weather","Payroll","Phone numbers"],"Hatch patterns represent materials.")
H('96.d.2.D',4,"A diagonal hatch with cross lines in a section drawing often shows:","Masonry",["Water","Glass","Sky"],"Pattern fill codes materials.")
H('96.d.2.E',3,"On plans, the abbreviation 'DR' usually means:","Door",["Drain","Drive","Draft"],"Abbreviations save space.")
H('96.d.2.E',4,"The abbreviation 'GYP BD' stands for:","Gypsum board",["Garage plan","Grade piping","Gutter pipe"],"Gypsum board is drywall.")
H('96.d.2.F',3,"A wall section is used to show:","Vertical construction layers of a wall",["Parking","Tax records","Phone lines"],"Sections cut through the assembly.")
H('96.d.2.F',4,"A door schedule lists each door's:","Size, type, and hardware",["Price at store","Owner's phone","Supplier's hours"],"Schedules organize repeated items.")
H('96.d.2.G',3,"Written specifications describe:","Materials, quality, and installation requirements",["Employee vacations","Billing hours","Break times"],"Specs supplement drawings.")
H('96.d.2.G',4,"If the drawings and specifications disagree, a builder should:","Ask the architect or supervisor for clarification",["Pick one","Ignore both","Flip a coin"],"Conflicts must be resolved before building.")
H('96.d.2.H',3,"Specifications are commonly organized into:","Divisions by type of work",["Random pages","Alphabetical jokes","Weather charts"],"CSI divisions organize specs.")
H('96.d.2.H',4,"A typical specification section includes General, Products, and:","Execution",["Entertainment","Discounts","Receipts"],"Three-part format is standard.")
H('96.d.2.I',3,"A quantity takeoff is a process of:","Counting and measuring materials from the plans",["Hiring workers","Painting walls","Hanging doors"],"Takeoffs support estimates.")
H('96.d.2.I',4,"A room is 10 feet by 12 feet. How many square feet of flooring are needed (no waste)?","120",["22","44","240"],"10 x 12 = 120.")
H('96.d.3.A',3,"A framing square is used to check:","Right angles",["Weight","Voltage","Temperature"],"Squares verify 90 degrees.")
H('96.d.3.A',4,"A coping saw is used to:","Cut curved profiles on trim for tight joints",["Cut sheet metal","Drive nails","Measure level"],"Coping fits molding over irregular walls.")
H('96.d.3.B',3,"Keeping a chisel sharp is a safety measure because a sharp chisel:","Requires less force and is less likely to slip",["Is more dangerous","Needs more force","Is quieter"],"Dull tools slip.")
H('96.d.3.B',4,"Hand tools should be stored:","Clean, dry, and in a secure place",["Wet on the ground","In rain","Loose in a pile"],"Proper storage prevents rust and damage.")
H('96.d.4.A',3,"A power miter saw is mainly used to make:","Accurate crosscuts and angled cuts",["Curved lines","Holes in concrete","Welds"],"Miter saws cut angles.")
H('96.d.4.A',4,"A pneumatic nailer is used to:","Drive nails quickly with compressed air",["Cut lumber","Measure lengths","Mix cement"],"Nailers speed fastening.")
H('96.d.4.B',3,"Before using a power nailer, you should check that the:","Safety contact tip works properly",["Color matches","Logo is visible","Trigger is taped"],"Never disable safety features.")
H('96.d.4.B',4,"Power tool blades should be:","Sharp and correct for the material",["Dull","Mismatched","Bent"],"Right blade, safe cut.")
H('96.d.5.A',3,"Newer technologies like laser measures require that users follow:","Manufacturer safety instructions",["No guidelines","Guesswork","Rumors"],"New tools have specific cautions.")
H('96.d.5.A',4,"Looking directly into a laser beam can:","Damage the eyes",["Warm the hands","Charge batteries","Improve sight"],"Laser safety includes eye protection.")
H('96.d.5.B',3,"Maintenance on a battery-powered tool includes:","Keeping batteries charged and contacts clean",["Soaking it","Painting it","Hammering it"],"Battery care extends tool life.")
H('96.d.5.B',4,"Dust buildup in a digital tool's vents can cause:","Overheating and failure",["Faster use","Cooler running","Longer life"],"Clean tools last.")
H('96.d.6.A',3,"When replacing a window, a worker should first:","Measure the opening and check for hazards",["Smash the glass","Skip measuring","Remove the whole wall"],"Careful removal and measuring come first.")
H('96.d.6.A',4,"A shim is used when installing a window to:","Make the unit plumb and level in the opening",["Cut the glass","Insulate","Paint trim"],"Shims adjust fit.")
H('96.d.6.B',3,"A vapor barrier is installed to:","Slow moisture movement into building materials",["Add weight","Add color","Increase noise"],"Moisture control protects structure.")
H('96.d.6.B',4,"Building paper or house wrap behind siding helps to:","Shed water while letting some vapor escape",["Hold nails only","Add heat","Hide studs"],"It acts as a water-resistive barrier.")
H('96.d.7.A',3,"Exterior siding should be installed over:","A weather-resistive barrier",["Bare air","Open studs only","Wet carpet"],"Barriers prevent leaks.")
H('96.d.7.A',4,"When installing siding, you should leave room for:","Expansion and contraction",["Insects","Paint","Dust"],"Materials move with temperature.")
H('96.d.7.B',3,"Siding is often fastened with:","Corrosion-resistant nails or screws",["Staples only","Tape","Glue only"],"Exterior fasteners resist rust.")
H('96.d.7.B',4,"Using the wrong fastener on siding can cause:","Rust stains and loose boards",["Better fit","Faster work","Added strength"],"Match fasteners to the siding.")
H('96.d.7.C',3,"Stucco is a plaster-like finish applied to:","Exterior walls",["Ceilings only","Pipes","Windows only"],"Stucco is a cement-based exterior finish.")
H('96.d.7.C',4,"Masonry veneer is a thin layer of:","Brick or stone attached to a wall",["Wood paneling","Vinyl","Carpet"],"Veneer is non-structural.")
H('96.d.7.D',3,"A common siding type used in many regions is:","Vinyl",["Cardboard","Glass","Foam only"],"Vinyl, wood, and fiber cement are common.")
H('96.d.7.D',4,"Fiber cement siding is valued for resisting:","Rot, insects, and fire",["Sunlight benefits","Stains from paint","Sound"],"It is durable and low maintenance.")
H('96.d.8.A',3,"A stud wall is laid out with studs typically spaced:","16 inches on center",["3 inches","60 inches","120 inches"],"16 inches is standard.")
H('96.d.8.A',4,"A partition wall is one that:","Divides space but may not carry structural load",["Always holds the roof","Is made only of glass","Cannot have doors"],"Partitions separate rooms.")
H('96.d.8.B',3,"Wood framing is commonly fastened with:","Nails or screws",["Rope","Tape","Paper clips"],"Standard fasteners join wood.")
H('96.d.8.B',4,"Two 16d nails through the end of a stud into the plate is called:","End nailing",["Toenailing","Clinching","Pocket screwing"],"End nailing fastens through the plate.")
H('96.d.8.C',3,"Steel studs are usually attached to tracks using:","Self-drilling screws",["Wood nails","Staples","Tape"],"Metal framing uses screws or crimping.")
