H('97.d.1.B',4,"A supervisor can promote on-site safety by:","Holding regular safety meetings",["Skipping meetings","Ignoring hazards","Hiding records"],"Toolbox talks keep safety in mind.")
H('97.d.1.C',3,"An electrical hazard is a:","Frayed extension cord",["Labeled panel","Grounded outlet","Closed junction box"],"Damaged cords can shock or start fires.")
