H('97.d.10',3,"Historic preservation means:","Protecting and maintaining significant older buildings",["Demolishing old buildings","Ignoring them","Painting them neon"],"Preservation keeps heritage structures.")
H('97.d.10',4,"Before altering a building in a local historic district, an owner often must get:","Approval from a historic review board",["No approval","A fishing license","A pet permit"],"Local rules guide changes.")
H('97.d.2.A',3,"A commercial blueprint set usually starts with a:","Cover sheet and index",["Song list","Menu","Brochure"],"The index lists sheets.")
